    releaseCoverEdit->setText("ui/mod-cover.png");

    teamInfoFileEdit->clear();
    teamInfoTextEdit->setPlainText(QString::fromUtf8(
        "MOD 制作：作者甲、作者乙\n程序：作者甲\n剧情：作者乙\n"));
    versionEdit->setText("1.041 中文版");
    releaseDescriptionFileEdit->clear();
    releaseDescriptionTextEdit->setPlainText(
        QString::fromUtf8("这是当前 MOD 的新简介。\n支持中文和空格路径。\n"));
