    ok = check(invoked, "invoke menu asset double click slot") && ok;
    ok = check(imageEdit->text() == newImage,
               "menu asset double click refreshes component image field immediately") && ok;

    invoked = QMetaObject::invokeMethod(&window, "onSaveFile", Qt::DirectConnection);
