// 全部图层拾取三层不同 tile 后，切到单层时画笔/预览应跟随到对应层数据。
bool testMapEditorAllLayersPickThenSwitchLayerRestoresBrush()
{
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create all-layers layer-switch temp dir"))
        return false;
    QDir root(tempDir.path());
    if (!check(root.mkpath("mpc/map"), "create all-layers layer-switch mpc/map dir"))
        return false;

    // 三个不同颜色的 MPC，分别作为地面/建筑/空中层图像，便于唯一识别。
    // 每个 MPC 提供 64 帧，使 frame=10/20/30 都在有效范围内（避免 spinbox setRange
    // 把越界 frame 夹到 0，从而无法区分各层 frame）。
    auto makeSolidMpc = [](const QColor& color) {
        MPCFileHead head = {};
        std::memcpy(head.head, "MPC File Ver2.0", 16);
        const int frameCount = 64;
        head.picCount = frameCount;
        head.paletteLen = 256;
        std::vector<uint8_t> buffer;
        appendValue(buffer, head);
        std::vector<ColorARGB> palette(256);
        palette[1] = {
            static_cast<uint8_t>(color.blue()),
            static_cast<uint8_t>(color.green()),
            static_cast<uint8_t>(color.red()),
            static_cast<uint8_t>(color.alpha())
        };
        const uint8_t* paletteBytes = reinterpret_cast<const uint8_t*>(palette.data());
        buffer.insert(buffer.end(), paletteBytes, paletteBytes + palette.size() * sizeof(ColorARGB));

        const int width = 64;
        const int height = 32;
        // 单帧 RLE 数据（全部用调色板索引 1）。
        std::vector<uint8_t> frameData;
        int remaining = width * height;
        while (remaining > 0)
        {
            int run = std::min(128, remaining);
            frameData.push_back(static_cast<uint8_t>(run));
            for (int i = 0; i < run; i++) frameData.push_back(1);
            remaining -= run;
        }
        // 帧偏移表：picCount 个 int32，相对 dataStart 的偏移。每帧布局相同，
        // 偏移按 0, frameSize, 2*frameSize, ... 递增。
        const size_t frameSize = sizeof(MPCPicHead) + frameData.size();
        for (int i = 0; i < frameCount; i++)
        {
            int32_t offset = static_cast<int32_t>(i * frameSize);
            appendValue(buffer, offset);
        }
        // 依次写入每帧的 MPCPicHead + frameData。
        for (int i = 0; i < frameCount; i++)
        {
            MPCPicHead picHead = {};
            picHead.dataLen = static_cast<int32_t>(sizeof(MPCPicHead) + frameData.size());
            picHead.width = width;
            picHead.height = height;
            appendValue(buffer, picHead);
            buffer.insert(buffer.end(), frameData.begin(), frameData.end());
        }
        return buffer;
    };

    auto groundMpc = makeSolidMpc(QColor(255, 30, 30, 255));
    auto buildingMpc = makeSolidMpc(QColor(30, 255, 30, 255));
    auto skyMpc = makeSolidMpc(QColor(30, 30, 255, 255));
    QString groundPath = root.filePath("mpc/map/ground.mpc");
    QString buildingPath = root.filePath("mpc/map/building.mpc");
    QString skyPath = root.filePath("mpc/map/sky.mpc");
    if (!check(Util::writeFileFromBuffer(groundPath.toUtf8().toStdString(), groundMpc.data(), groundMpc.size()),
               "write all-layers layer-switch ground MPC fixture") ||
        !check(Util::writeFileFromBuffer(buildingPath.toUtf8().toStdString(), buildingMpc.data(), buildingMpc.size()),
               "write all-layers layer-switch building MPC fixture") ||
        !check(Util::writeFileFromBuffer(skyPath.toUtf8().toStdString(), skyMpc.data(), skyMpc.size()),
               "write all-layers layer-switch sky MPC fixture"))
    {
        return false;
    }

    MapEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.setAssetsBasePath(root.absolutePath());
    window.resize(1000, 720);
    window.show();
    QApplication::processEvents();
    if (!check(window.createNewMap(8, 8), "layer-switch test creates new map"))
        return false;
    QApplication::processEvents();

    MapRenderCanvas* canvas = window.findChild<MapRenderCanvas*>();
    QComboBox* paintLayerCombo = window.findChild<QComboBox*>("mapPaintLayerCombo");
    QComboBox* mpcComboBox = window.findChild<QComboBox*>("mapMpcComboBox");
    QSpinBox* frameSpinBox = window.findChild<QSpinBox*>("mapFrameSpinBox");
    if (!check(canvas != nullptr && paintLayerCombo != nullptr &&
              mpcComboBox != nullptr && frameSpinBox != nullptr,
              "layer-switch test controls exist"))
    {
        window.close();
        return false;
    }

    // 设置三个 MPC 槽位：slot0=ground, slot1=building, slot2=sky。
    // 槽位 stored value = slot+1，即 ground=1, building=2, sky=3。
    MpcInfoData groundInfo;
    groundInfo.name = "ground.mpc";
    window.getMapEditorRef().setMpcInfo(0, groundInfo);
    MpcInfoData buildingInfo;
    buildingInfo.name = "building.mpc";
    window.getMapEditorRef().setMpcInfo(1, buildingInfo);
    MpcInfoData skyInfo;
    skyInfo.name = "sky.mpc";
    window.getMapEditorRef().setMpcInfo(2, skyInfo);
    window.refreshMpcPreviewForTest();
    QApplication::processEvents();

    // 在地图 (3,2) 写入三层不同的源瓦片：layer0=ground(1)/f10, layer1=building(2)/f20, layer2=sky(3)/f30。
    MapTileData src;
    src.layer[0].mpc = 1;
    src.layer[0].frame = 10;
    src.layer[1].mpc = 2;
    src.layer[1].frame = 20;
    src.layer[2].mpc = 3;
    src.layer[2].frame = 30;
    window.getMapEditorRef().setTile(3, 2, src);

    // 进入全部图层模式，把该瓦片作为多层画笔。
    canvas->setPaintAllLayers(true);
    MapTileData brushTile;
    brushTile.layer[0] = src.layer[0];
    brushTile.layer[1] = src.layer[1];
    brushTile.layer[2] = src.layer[2];
    canvas->setMultiLayerPaintBrush(brushTile, true);
    QApplication::processEvents();

    bool ok = true;

    // 辅助：通过 paintLayerCombo 切换到指定图层（触发 onPaintLayerChanged）。
    auto switchLayerViaCombo = [&](int layer) {
        for (int i = 0; i < paintLayerCombo->count(); i++)
        {
            if (paintLayerCombo->itemData(i).toInt() == layer)
            {
                paintLayerCombo->setCurrentIndex(i);
                break;
            }
        }
        QApplication::processEvents();
    };
    // 通过 combo 进入全部图层模式（itemData=-1）。切到单层前先确保 combo 真正在
    // 全部图层项，否则 setCurrentIndex 不会改变索引、不会触发 onPaintLayerChanged。
    auto enterAllLayersViaCombo = [&]() {
        for (int i = 0; i < paintLayerCombo->count(); i++)
        {
            if (paintLayerCombo->itemData(i).toInt() == -1)
            {
                paintLayerCombo->setCurrentIndex(i);
                break;
            }
        }
        QApplication::processEvents();
        canvas->setMultiLayerPaintBrush(brushTile, true);
        QApplication::processEvents();
    };

    // 先通过 combo 进入全部图层（这样后续切到地面层 combo 索引才会真正变化）。
    enterAllLayersViaCombo();

    // 切到地面层(0)：画笔/预览应跟随到 layer0 = ground(1)/f10。
    switchLayerViaCombo(0);
    ok = check(canvas->getPaintLayer() == 0, "layer-switch to ground sets canvas paint layer 0") && ok;
    ok = check(!canvas->isPaintAllLayers(), "layer-switch to ground leaves all-layers mode") && ok;
    ok = check(canvas->getPaintMpcIndex() == 1, "layer-switch to ground restores ground mpc index") && ok;
    ok = check(canvas->getPaintFrameIndex() == 10, "layer-switch to ground restores ground frame index") && ok;
    ok = check(mpcComboBox->currentData().toInt() == 1, "layer-switch to ground syncs mpc combo") && ok;
    ok = check(frameSpinBox->value() == 10, "layer-switch to ground syncs frame spinbox") && ok;

    // 切到建筑层(1)：应跟随到 layer1 = building(2)/f20。
    // 注意：切回全部图层重新装填多层画笔，再切建筑层，验证多层画笔在各层切换都有效。
    enterAllLayersViaCombo();
    switchLayerViaCombo(1);
    ok = check(canvas->getPaintLayer() == 1, "layer-switch to building sets canvas paint layer 1") && ok;
    ok = check(canvas->getPaintMpcIndex() == 2, "layer-switch to building restores building mpc index") && ok;
    ok = check(canvas->getPaintFrameIndex() == 20, "layer-switch to building restores building frame index") && ok;
    ok = check(mpcComboBox->currentData().toInt() == 2, "layer-switch to building syncs mpc combo") && ok;
    ok = check(frameSpinBox->value() == 20, "layer-switch to building syncs frame spinbox") && ok;

    // 切到空中层(2)：应跟随到 layer2 = sky(3)/f30。
    enterAllLayersViaCombo();
    switchLayerViaCombo(2);
    ok = check(canvas->getPaintLayer() == 2, "layer-switch to sky sets canvas paint layer 2") && ok;
    ok = check(canvas->getPaintMpcIndex() == 3, "layer-switch to sky restores sky mpc index") && ok;
    ok = check(canvas->getPaintFrameIndex() == 30, "layer-switch to sky restores sky frame index") && ok;
    ok = check(mpcComboBox->currentData().toInt() == 3, "layer-switch to sky syncs mpc combo") && ok;
    ok = check(frameSpinBox->value() == 30, "layer-switch to sky syncs frame spinbox") && ok;

    // createNewMap 会把 isModified 置 true，close 时 confirmSaveIfModified 会弹模态
    // 对话框阻塞测试。先保存地图（复用既有 fixture 写法）清掉 isModified 再关闭。
    const QString mapPath = QDir(tempDir.path()).filePath("layer-switch.map");
    ok = check(window.saveMapFile(mapPath),
               "layer-switch test saves map before closing window") && ok;

    window.close();
    QApplication::processEvents();
    return ok;
}

// 单图层画笔 hover 与全部图层多层画笔 hover 的半透明笔刷预览渲染。
// 顶部/底部边缘渲染：高图像 tile 靠近屏幕边缘时图像应伸入视口而不被裁掉。
bool testMapCanvasMouseEditingSignalsAndDataStayInSync()
{
    std::vector<uint8_t> buffer = makeEmptyMapBuffer(8, 8);
    MapFileEditor editor;
    if (!check(editor.loadFromBuffer(buffer.data(), buffer.size()), "load map mouse interaction test map"))
        return false;

    MapTileData sourceTile = makeMarkerTile(5);
    sourceTile.layer[2].mpc = 77;
    sourceTile.layer[2].frame = 88;
    editor.setTile(2, 2, sourceTile);

    MapRenderCanvas canvas;
    canvas.setAttribute(Qt::WA_DontShowOnScreen, true);
    canvas.resize(800, 600);
    canvas.setMapFileEditor(&editor);
    canvas.centerOnTile(3, 3);
    canvas.show();
    QApplication::processEvents();

    bool ok = true;
    int hoveredX = -1;
    int hoveredY = -1;
    int clickedX = -1;
    int clickedY = -1;
    Qt::MouseButton clickedButton = Qt::NoButton;
    int pickedMpc = -1;
    int pickedFrame = -1;
    int pickedLayer = -1;
    int editedCount = 0;
    int placedCount = 0;
    int movedCount = 0;
    int zoomSignalCount = 0;
    int toolChangedCount = 0;

    QObject::connect(&canvas, &MapRenderCanvas::tileHovered, [&](int x, int y)
    {
        hoveredX = x;
        hoveredY = y;
    });
    QObject::connect(&canvas, &MapRenderCanvas::tileClicked, [&](int x, int y, Qt::MouseButton button)
    {
        clickedX = x;
        clickedY = y;
        clickedButton = button;
    });
    QObject::connect(&canvas, &MapRenderCanvas::tilePicked,
        [&](int mpc, int frame, int layer, int, int)
    {
        pickedMpc = mpc;
        pickedFrame = frame;
        pickedLayer = layer;
    });
    bool pickedAllLayersEmitted = false;
    MapTileData pickedAllLayersTile;
    QObject::connect(&canvas, &MapRenderCanvas::tilePickedAllLayers,
        [&](const MapTileData& tileData, int, int)
    {
        pickedAllLayersEmitted = true;
        pickedAllLayersTile = tileData;
    });
    QObject::connect(&canvas, &MapRenderCanvas::tileEdited, [&](int, int)
    {
        editedCount++;
    });
    QObject::connect(&canvas, &MapRenderCanvas::entityPlaced, [&](int, bool)
    {
        placedCount++;
    });
    QObject::connect(&canvas, &MapRenderCanvas::entityMoved, [&](int, bool, int, int)
    {
        movedCount++;
    });
    QObject::connect(&canvas, &MapRenderCanvas::zoomChanged, [&](float)
    {
        zoomSignalCount++;
    });
    QObject::connect(&canvas, &MapRenderCanvas::editToolChanged, [&](MapEditTool)
    {
        toolChangedCount++;
    });

    auto tileCenter = [&](int x, int y) {
        QPoint center = canvas.tileToScreenCenter(x, y);
        if (!canvas.rect().contains(center))
        {
            canvas.centerOnTile(x, y);
            QApplication::processEvents();
            center = canvas.tileToScreenCenter(x, y);
        }
        return center;
    };

    QPoint tile22 = tileCenter(2, 2);
    ok = check(canvas.rect().contains(tile22), "map tile 2,2 screen center is visible") && ok;

    sendMapMouseEvent(canvas, QEvent::MouseMove, tile22, Qt::NoButton, Qt::NoButton);
    ok = check(canvas.getHoverTileX() == 2 && canvas.getHoverTileY() == 2,
               "map hover tile coordinates update from mouse move") && ok;
    ok = check(hoveredX == 2 && hoveredY == 2,
               "map hover signal matches current hover tile") && ok;

    canvas.setEditTool(MapEditTool::Select);
    sendMapMouseEvent(canvas, QEvent::MouseButtonPress, tile22, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, tile22, Qt::LeftButton, Qt::NoButton);
    ok = check(canvas.getSelectedTileX() == 2 && canvas.getSelectedTileY() == 2,
               "map left click stores selected tile") && ok;
    ok = check(clickedX == 2 && clickedY == 2 && clickedButton == Qt::LeftButton,
               "map left click signal matches selected tile") && ok;
    // 默认绘制图层为地面层(0)：tile 2,2 三层都非空时，拾取当前绘制图层(0)
    ok = check(pickedMpc == 5 && pickedFrame == 15 && pickedLayer == 0,
               "map left click picks current paint layer when non-empty") && ok;

    // 为后续不同图层的拾取准备独立的 marker tile（避免同一 tile 重复点击触发
    // 选择切换分支，从而跳过拾取）。每次拾取前先点空 tile 重置选中瓦片。
    MapTileData fullTileA = makeMarkerTile(6);
    fullTileA.layer[2].mpc = 78;
    fullTileA.layer[2].frame = 89;
    editor.setTile(3, 1, fullTileA);
    MapTileData fullTileB = makeMarkerTile(7);
    fullTileB.layer[2].mpc = 79;
    fullTileB.layer[2].frame = 90;
    editor.setTile(4, 1, fullTileB);
    MapTileData fullTileC = makeMarkerTile(8);
    fullTileC.layer[2].mpc = 80;
    fullTileC.layer[2].frame = 91;
    editor.setTile(5, 1, fullTileC);
    auto pickOn = [&](int tx, int ty) {
        // 先点空瓦片(0,0)清除选中状态，避免选中瓦片==拾取瓦片触发切换分支
        QPoint empty = tileCenter(0, 0);
        sendMapMouseEvent(canvas, QEvent::MouseButtonPress, empty, Qt::LeftButton, Qt::LeftButton);
        sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, empty, Qt::LeftButton, Qt::NoButton);
        pickedMpc = pickedFrame = pickedLayer = -1;
        pickedAllLayersEmitted = false;
        pickedAllLayersTile = MapTileData();
        QPoint target = tileCenter(tx, ty);
        sendMapMouseEvent(canvas, QEvent::MouseButtonPress, target, Qt::LeftButton, Qt::LeftButton);
        sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, target, Qt::LeftButton, Qt::NoButton);
    };

    // 切到建筑层(1)后拾取，应得到建筑层而非最高层
    canvas.setPaintLayer(1);
    pickOn(3, 1);
    ok = check(pickedMpc == 26 && pickedFrame == 36 && pickedLayer == 1,
               "map pick prefers current paint layer (building) over higher layers") && ok;

    // 切到空中层(2)后拾取，应得到空中层
    canvas.setPaintLayer(2);
    pickOn(4, 1);
    ok = check(pickedMpc == 79 && pickedFrame == 90 && pickedLayer == 2,
               "map pick prefers current paint layer (sky)") && ok;

    // 全部图层模式下，左键单点拾取应读取三层 tile 数据，
    // 不再回退为最高非空单层（也不再发出 tilePicked 单层信号）。
    // 准备一个三层各有不同数据的源瓦片 (6,1)。
    MapTileData sourceAllLayers = makeMarkerTile(9);
    sourceAllLayers.layer[0].mpc = 11;
    sourceAllLayers.layer[0].frame = 12;
    sourceAllLayers.layer[1].mpc = 21;
    sourceAllLayers.layer[1].frame = 22;
    sourceAllLayers.layer[2].mpc = 31;
    sourceAllLayers.layer[2].frame = 32;
    editor.setTile(6, 1, sourceAllLayers);

    canvas.setPaintAllLayers(true);
    pickOn(6, 1);
    ok = check(pickedAllLayersEmitted,
               "map all-layers pick emits tilePickedAllLayers") && ok;
    ok = check(pickedMpc == -1,
               "map all-layers pick does not emit single-layer tilePicked") && ok;
    ok = check(pickedAllLayersTile.layer[0].mpc == 11 && pickedAllLayersTile.layer[0].frame == 12 &&
                   pickedAllLayersTile.layer[1].mpc == 21 && pickedAllLayersTile.layer[1].frame == 22 &&
                   pickedAllLayersTile.layer[2].mpc == 31 && pickedAllLayersTile.layer[2].frame == 32,
               "map all-layers pick reads all three tile layers") && ok;
    ok = check(canvas.isPaintAllLayers(),
               "map all-layers pick keeps all-layers mode") && ok;
    ok = check(canvas.hasMultiLayerPaintBrush(),
               "map all-layers pick stores multi-layer paint brush") && ok;

    // 右键绘制到另一个格子 (7,1)，目标三层应分别等于源三层。
    QPoint target71 = tileCenter(7, 1);
    int editedBeforeMultiPaint = editedCount;
    sendMapMouseEvent(canvas, QEvent::MouseButtonPress, target71, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, target71, Qt::RightButton, Qt::NoButton);
    MapTileData destAfterMultiPaint = editor.getTile(7, 1);
    ok = check(destAfterMultiPaint.layer[0].mpc == 11 && destAfterMultiPaint.layer[0].frame == 12 &&
                   destAfterMultiPaint.layer[1].mpc == 21 && destAfterMultiPaint.layer[1].frame == 22 &&
                   destAfterMultiPaint.layer[2].mpc == 31 && destAfterMultiPaint.layer[2].frame == 32,
               "map all-layers paint writes three layers separately from multi-layer brush") && ok;
    ok = check(editedCount > editedBeforeMultiPaint,
               "map all-layers paint emits tileEdited") && ok;
    canvas.setPaintAllLayers(false);

    canvas.setPaintLayer(1);
    canvas.setPaintMpcIndex(44);
    canvas.setPaintFrameIndex(55);
    QPoint tile32 = tileCenter(3, 2);
    int editedBeforeRightPaint = editedCount;
    sendMapMouseEvent(canvas, QEvent::MouseButtonPress, tile32, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, tile32, Qt::RightButton, Qt::NoButton);
    MapTileLayerData paintedLayer = editor.getTileLayer(3, 2, 1);
    ok = check(paintedLayer.mpc == 44 && paintedLayer.frame == 55,
               "map right click paints current brush to selected layer") && ok;
    ok = check(editedCount > editedBeforeRightPaint,
               "map right click paint emits tileEdited") && ok;

    // 障碍/陷阱工具交互与 Tile 工具一致：左键拾取（不修改地图），右键绘制当前画笔值。
    canvas.setEditTool(MapEditTool::ObstaclePaint);
    canvas.setPaintObstacle(0x80);
    // 先用右键在 (1,1) 绘制障碍 0x80
    QPoint tile11 = tileCenter(1, 1);
    sendMapMouseEvent(canvas, QEvent::MouseButtonPress, tile11, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, tile11, Qt::RightButton, Qt::NoButton);
    ok = check(editor.getTileObstacle(1, 1) == 0x80,
               "map obstacle tool right click paints current brush obstacle") && ok;
    // 左键拾取应读取障碍值且不修改地图
    int pickedObstacle = -1;
    QObject::connect(&canvas, &MapRenderCanvas::obstaclePicked, [&](uint8_t obs, int, int) {
        pickedObstacle = obs;
    });
    canvas.setPaintObstacle(0x40);
    sendMapMouseEvent(canvas, QEvent::MouseButtonPress, tile11, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, tile11, Qt::LeftButton, Qt::NoButton);
    ok = check(pickedObstacle == 0x80,
               "map obstacle tool left click picks obstacle from map") && ok;
    ok = check(editor.getTileObstacle(1, 1) == 0x80,
               "map obstacle tool left click does not modify map") && ok;

    canvas.setEditTool(MapEditTool::TrapPaint);
    canvas.setPaintTrapIndex(7);
    // 先用右键在 (1,2) 绘制陷阱 7
    QPoint tile12 = tileCenter(1, 2);
    sendMapMouseEvent(canvas, QEvent::MouseButtonPress, tile12, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, tile12, Qt::RightButton, Qt::NoButton);
    ok = check(editor.getTileTrap(1, 2) == 7,
               "map trap tool right click paints current brush trap") && ok;
    // 左键拾取应读取陷阱值且不修改地图
    int pickedTrap = -1;
    QObject::connect(&canvas, &MapRenderCanvas::trapPicked, [&](uint8_t trap, int, int) {
        pickedTrap = trap;
    });
    canvas.setPaintTrapIndex(3);
    sendMapMouseEvent(canvas, QEvent::MouseButtonPress, tile12, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, tile12, Qt::LeftButton, Qt::NoButton);
    ok = check(pickedTrap == 7,
               "map trap tool left click picks trap from map") && ok;
    ok = check(editor.getTileTrap(1, 2) == 7,
               "map trap tool left click does not modify map") && ok;

    MapEntityData entity;
    entity.name = "PlacedNpc";
    entity.iniFile = "ini/npc/test.ini";
    entity.isNpc = true;
    canvas.setContinuousPlace(false);
    canvas.setPlacingEntity(entity);
    canvas.setEditTool(MapEditTool::NpcPlace);
    QPoint tile44 = tileCenter(4, 4);
    sendMapMouseEvent(canvas, QEvent::MouseButtonPress, tile44, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, tile44, Qt::LeftButton, Qt::NoButton);
    ok = check(canvas.getNpcList().size() == 1 && canvas.getNpcList()[0].mapX == 4 && canvas.getNpcList()[0].mapY == 4,
               "map NPC placement writes entity to list at clicked tile") && ok;
    ok = check(placedCount == 1, "map NPC placement emits entityPlaced") && ok;
    ok = check(canvas.getEditTool() == MapEditTool::Select,
               "map NPC placement returns to select tool when not continuous") && ok;

    QPoint tile54 = tileCenter(5, 4);
    sendMapMouseEvent(canvas, QEvent::MouseButtonPress, tile44, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(canvas, QEvent::MouseMove, tile54, Qt::NoButton, Qt::LeftButton);
    sendMapMouseEvent(canvas, QEvent::MouseButtonRelease, tile54, Qt::LeftButton, Qt::NoButton);
    ok = check(canvas.getNpcList()[0].mapX == 5 && canvas.getNpcList()[0].mapY == 4,
               "map selected NPC drag updates entity coordinates") && ok;
    ok = check(movedCount == 1, "map selected NPC drag emits entityMoved once") && ok;

    float zoomBefore = canvas.getZoomLevel();
    QPointF wheelPoint(tileCenter(3, 3));
    QWheelEvent wheelEvent(
        wheelPoint,
        wheelPoint,
        QPoint(),
        QPoint(0, 120),
        Qt::NoButton,
        Qt::NoModifier,
        Qt::NoScrollPhase,
        false);
    QApplication::sendEvent(&canvas, &wheelEvent);
    ok = check(canvas.getZoomLevel() > zoomBefore,
               "map mouse wheel zooms in around cursor") && ok;
    ok = check(zoomSignalCount > 0, "map mouse wheel emits zoomChanged") && ok;
    ok = check(toolChangedCount > 0, "map edit tool changes emit synchronization signal") && ok;

    canvas.close();
    QApplication::processEvents();
    return ok;
}

bool testMapEditorWindowUndoRedoRestoresPaintedTile()
{
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create map editor undo redo temp dir"))
        return false;

    MapEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.resize(900, 650);
    window.show();
    QApplication::processEvents();

    if (!check(window.createNewMap(6, 6), "map editor creates new map for undo redo test"))
        return false;

    MapRenderCanvas* canvas = window.findChild<MapRenderCanvas*>();
    QAction* undoAction = window.findChild<QAction*>("actionUndo");
    QAction* redoAction = window.findChild<QAction*>("actionRedo");
    if (!check(canvas != nullptr && undoAction != nullptr && redoAction != nullptr,
            "map editor undo redo controls exist"))
    {
        return false;
    }

    canvas->setPaintLayer(0);
    canvas->setPaintMpcIndex(23);
    canvas->setPaintFrameIndex(34);
    canvas->centerOnTile(2, 2);
    QApplication::processEvents();

    QPoint tileCenter = canvas->tileToScreenCenter(2, 2);
    bool ok = check(canvas->rect().contains(tileCenter),
                    "map editor undo redo test tile is visible");
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tileCenter, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tileCenter, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();

    const QString paintedMapPath = QDir(tempDir.path()).filePath("painted.map");
    ok = check(window.saveMapFile(paintedMapPath), "save painted map after window paint") && ok;
    MapFileEditor paintedEditor;
    ok = check(paintedEditor.loadFromFile(paintedMapPath.toUtf8().toStdString()),
               "reload painted map for verification") && ok;
    ok = check(paintedEditor.getTileLayer(2, 2, 0).mpc == 23
            && paintedEditor.getTileLayer(2, 2, 0).frame == 34,
            "map editor right click paint is saved") && ok;
    ok = check(undoAction->isEnabled(), "map editor enables undo after paint") && ok;

    const QString emptyNpcPath = QDir(tempDir.path()).filePath("empty.npc");
    ok = check(writeUtf8TextFile(emptyNpcPath, "[Head]\nCount=0\n") &&
                   window.loadNpcListFromFile(emptyNpcPath, false) &&
                   undoAction->isEnabled(),
               "loading NPC list preserves unrelated map undo history") && ok;

    undoAction->trigger();
    QApplication::processEvents();
    const QString undoneMapPath = QDir(tempDir.path()).filePath("undone.map");
    ok = check(window.saveMapFile(undoneMapPath), "save map after undo") && ok;
    MapFileEditor undoneEditor;
    ok = check(undoneEditor.loadFromFile(undoneMapPath.toUtf8().toStdString()),
               "reload undone map for verification") && ok;
    ok = check(undoneEditor.getTileLayer(2, 2, 0).mpc == 0
            && undoneEditor.getTileLayer(2, 2, 0).frame == 0,
            "map editor undo restores old tile data") && ok;
    ok = check(redoAction->isEnabled(), "map editor enables redo after undo") && ok;

    redoAction->trigger();
    QApplication::processEvents();
    const QString redoneMapPath = QDir(tempDir.path()).filePath("redone.map");
    ok = check(window.saveMapFile(redoneMapPath), "save map after redo") && ok;
    MapFileEditor redoneEditor;
    ok = check(redoneEditor.loadFromFile(redoneMapPath.toUtf8().toStdString()),
               "reload redone map for verification") && ok;
    ok = check(redoneEditor.getTileLayer(2, 2, 0).mpc == 23
            && redoneEditor.getTileLayer(2, 2, 0).frame == 34,
            "map editor redo reapplies painted tile data") && ok;

    window.close();
    QApplication::processEvents();
    return ok;
}

bool testMapEditorWindowUndoRedoRestoresMovedEntity()
{
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create map editor entity undo redo temp dir"))
        return false;

    QDir root(tempDir.path());
    const QString npcPath = root.filePath("move_npc.ini");
    bool ok = check(writeUtf8TextFile(npcPath,
        "[Head]\n"
        "Count=1\n"
        "\n"
        "[NPC000]\n"
        "Name=MoveNpc\n"
        "NPCIni=ini/npc/move.ini\n"
        "MapX=1\n"
        "MapY=1\n"),
        "write map editor entity undo redo NPC fixture");
    if (!ok)
        return false;

    MapEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.resize(900, 650);
    window.show();
    QApplication::processEvents();

    if (!check(window.createNewMap(8, 8), "map editor creates new map for entity undo redo test"))
        return false;
    window.loadNpcListFromFile(npcPath, false);
    QApplication::processEvents();

    MapRenderCanvas* canvas = window.findChild<MapRenderCanvas*>();
    QAction* undoAction = window.findChild<QAction*>("actionUndo");
    QAction* redoAction = window.findChild<QAction*>("actionRedo");
    QCheckBox* saveNpcWithMapCheck = window.findChild<QCheckBox*>("mapSaveNpcWithMapCheck");
    if (!check(canvas != nullptr && undoAction != nullptr && redoAction != nullptr
            && saveNpcWithMapCheck != nullptr,
            "map editor entity undo redo controls exist"))
    {
        return false;
    }

    canvas->centerOnTile(1, 1);
    QApplication::processEvents();
    QPoint fromPoint = canvas->tileToScreenCenter(1, 1);
    QPoint toPoint = canvas->tileToScreenCenter(3, 2);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, fromPoint, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(*canvas, QEvent::MouseMove, toPoint, Qt::NoButton, Qt::LeftButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, toPoint, Qt::LeftButton, Qt::NoButton);
    QApplication::processEvents();

    ok = check(canvas->getNpcList().size() == 1
            && canvas->getNpcList()[0].mapX == 3
            && canvas->getNpcList()[0].mapY == 2,
            "map editor entity drag moves NPC through window interaction") && ok;
    ok = check(undoAction->isEnabled(), "map editor enables undo after entity move") && ok;

    undoAction->trigger();
    QApplication::processEvents();
    ok = check(canvas->getNpcList()[0].mapX == 1 && canvas->getNpcList()[0].mapY == 1,
               "map editor undo restores moved NPC coordinates") && ok;
    ok = check(redoAction->isEnabled(), "map editor enables redo after entity move undo") && ok;

    redoAction->trigger();
    QApplication::processEvents();
    ok = check(canvas->getNpcList()[0].mapX == 3 && canvas->getNpcList()[0].mapY == 2,
               "map editor redo reapplies moved NPC coordinates") && ok;

    saveNpcWithMapCheck->setChecked(true);
    const QString mapPath = root.filePath("entity-undo-redo.map");
    ok = check(window.saveMapFile(mapPath),
               "map editor entity undo redo test saves map and NPC list before closing") && ok;

    window.close();
    QApplication::processEvents();
    return ok;
}

bool testMapObstacleTrapToolInteraction()
{
    // 障碍/陷阱工具交互回归测试：左键拾取、右键绘制、不修改地图、撤销重做、互不覆盖、边界。
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create obstacle trap interaction temp dir"))
        return false;

    MapEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.resize(900, 650);
    window.show();
    QApplication::processEvents();

    if (!check(window.createNewMap(6, 6), "obstacle trap test creates new map"))
        return false;

    MapRenderCanvas* canvas = window.findChild<MapRenderCanvas*>();
    QAction* undoAction = window.findChild<QAction*>("actionUndo");
    QAction* redoAction = window.findChild<QAction*>("actionRedo");
    QComboBox* obstacleCombo = window.findChild<QComboBox*>("mapObstacleComboBox");
    if (!check(canvas != nullptr && undoAction != nullptr && redoAction != nullptr &&
                   obstacleCombo != nullptr,
               "obstacle trap test controls exist"))
    {
        return false;
    }

    canvas->centerOnTile(2, 2);
    QApplication::processEvents();

    bool ok = true;

    auto tileCenter = [&](int x, int y) {
        QPoint center = canvas->tileToScreenCenter(x, y);
        if (!canvas->rect().contains(center))
        {
            canvas->centerOnTile(x, y);
            QApplication::processEvents();
            center = canvas->tileToScreenCenter(x, y);
        }
        return center;
    };

    // 1. 右键绘制障碍
    canvas->setEditTool(MapEditTool::ObstaclePaint);
    canvas->setPaintObstacle(0x80);
    QPoint tile22 = tileCenter(2, 2);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile22, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile22, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileObstacle(2, 2) == 0x80,
               "obstacle tool right click draws obstacle") && ok;

    // 2. 左键拾取障碍（不修改地图）
    int pickedObstacle = -1;
    QObject::connect(canvas, &MapRenderCanvas::obstaclePicked, [&](uint8_t obs, int, int) {
        pickedObstacle = obs;
    });
    canvas->setPaintObstacle(0x40);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile22, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile22, Qt::LeftButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(pickedObstacle == 0x80,
               "obstacle tool left click picks obstacle from map") && ok;
    ok = check(window.getMapEditor().getTileObstacle(2, 2) == 0x80,
               "obstacle tool left click does not modify map") && ok;

    MapTileData combinedObstacleTile = window.getMapEditor().getTile(2, 2);
    combinedObstacleTile.obstacle = 0x81;
    window.getMapEditorRef().setTile(2, 2, combinedObstacleTile);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile22, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile22, Qt::LeftButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(obstacleCombo->currentData().toInt() == 0x81 &&
                   obstacleCombo->currentText().contains("0X81", Qt::CaseInsensitive),
               "combined obstacle pick keeps UI and brush on custom byte value") && ok;

    // 3. 右键绘制陷阱
    canvas->setEditTool(MapEditTool::TrapPaint);
    canvas->setPaintTrapIndex(7);
    QPoint tile33 = tileCenter(3, 3);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile33, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile33, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileTrap(3, 3) == 7,
               "trap tool right click draws trap") && ok;

    // 4. 左键拾取陷阱（不修改地图）
    int pickedTrap = -1;
    QObject::connect(canvas, &MapRenderCanvas::trapPicked, [&](uint8_t trap, int, int) {
        pickedTrap = trap;
    });
    canvas->setPaintTrapIndex(3);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile33, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile33, Qt::LeftButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(pickedTrap == 7,
               "trap tool left click picks trap from map") && ok;
    ok = check(window.getMapEditor().getTileTrap(3, 3) == 7,
               "trap tool left click does not modify map") && ok;

    // 5. 障碍与陷阱互不覆盖：在同一瓦片上绘制障碍后绘制陷阱，障碍值应不变
    canvas->setEditTool(MapEditTool::ObstaclePaint);
    canvas->setPaintObstacle(0xA0);
    QPoint tile44 = tileCenter(4, 4);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile44, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile44, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    canvas->setEditTool(MapEditTool::TrapPaint);
    canvas->setPaintTrapIndex(5);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile44, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile44, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileObstacle(4, 4) == 0xA0,
               "obstacle and trap do not overwrite each other (obstacle preserved)") && ok;
    ok = check(window.getMapEditor().getTileTrap(4, 4) == 5,
               "obstacle and trap do not overwrite each other (trap preserved)") && ok;
    // 同时验证 Tile 图层未被障碍/陷阱工具修改
    MapTileData fullTile = window.getMapEditor().getTile(4, 4);
    ok = check(fullTile.layer[0].mpc == 0 && fullTile.layer[1].mpc == 0 && fullTile.layer[2].mpc == 0,
               "obstacle/trap tool does not modify tile layers") && ok;

    // 6. 右键修改可撤销、重做
    ok = check(undoAction->isEnabled(), "obstacle/trap undo is enabled after right click draws") && ok;
    undoAction->trigger();
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileTrap(4, 4) == 0,
               "obstacle/trap undo restores trap to 0") && ok;
    ok = check(window.getMapEditor().getTileObstacle(4, 4) == 0xA0,
               "obstacle/trap undo does not revert obstacle (only last command reverted)") && ok;
    ok = check(redoAction->isEnabled(), "obstacle/trap redo is enabled after undo") && ok;
    redoAction->trigger();
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileTrap(4, 4) == 5,
               "obstacle/trap redo reapplies trap") && ok;

    // 7. 边界方格：在 (0,0) 和 (5,5) 右键绘制障碍。
    // 注意：每次 tileCenter 可能重新定位画布，使之前的屏幕坐标失效，
    // 因此后续步骤必须重新计算坐标。
    canvas->setEditTool(MapEditTool::ObstaclePaint);
    canvas->setPaintObstacle(0x40);
    QPoint tile00 = tileCenter(0, 0);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile00, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile00, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileObstacle(0, 0) == 0x40,
               "obstacle tool right click works on boundary tile (0,0)") && ok;
    QPoint tile55 = tileCenter(5, 5);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile55, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile55, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileObstacle(5, 5) == 0x40,
               "obstacle tool right click works on boundary tile (5,5)") && ok;

    // 8. 左键拾取在边界方格也正常工作。
    // tile00 在 step 7 的 tileCenter(5,5) 后已失效，必须重新计算。
    pickedObstacle = -1;
    tile00 = tileCenter(0, 0);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile00, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile00, Qt::LeftButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(pickedObstacle == 0x40,
               "obstacle tool left click picks from boundary tile (0,0)") && ok;

    // 9. 右键拖动连续绘制障碍：从 (1,1) 拖到 (1,3)，每个瓦片都应被绘制。
    // 拖动过程中不重复绘制同一瓦片，每个新瓦片产生独立的撤销记录。
    canvas->setEditTool(MapEditTool::ObstaclePaint);
    canvas->setPaintObstacle(0x80);
    QPoint dragStart = tileCenter(1, 1);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, dragStart, Qt::RightButton, Qt::RightButton);
    QApplication::processEvents();
    // 拖到 (1,2)
    QPoint dragMid = tileCenter(1, 2);
    sendMapMouseEvent(*canvas, QEvent::MouseMove, dragMid, Qt::NoButton, Qt::RightButton);
    QApplication::processEvents();
    // 拖到 (1,3)
    QPoint dragEnd = tileCenter(1, 3);
    sendMapMouseEvent(*canvas, QEvent::MouseMove, dragEnd, Qt::NoButton, Qt::RightButton);
    QApplication::processEvents();
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, dragEnd, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileObstacle(1, 1) == 0x80,
               "obstacle right-drag draws start tile (1,1)") && ok;
    ok = check(window.getMapEditor().getTileObstacle(1, 2) == 0x80,
               "obstacle right-drag draws mid tile (1,2)") && ok;
    ok = check(window.getMapEditor().getTileObstacle(1, 3) == 0x80,
               "obstacle right-drag draws end tile (1,3)") && ok;

    // 窗口修改过地图，close 时会弹"是否保存"确认。用自动关闭器选择 Discard。
    {
        ModalDialogAutoCloser closer;
        window.close();
        QApplication::processEvents();
    }
    return ok;
}

// 障碍/陷阱交互的补充边界用例，覆盖主交互测试未触及的场景：
//   - 陷阱工具右键拖动连续绘制多个瓦片（主测试只覆盖了障碍拖动）；
//   - 画布缩放后 tileToScreenCenter 仍能正确命中目标瓦片并绘制障碍；
//   - 区域粘贴不会用剪贴板里的障碍/陷阱覆盖目标瓦片——粘贴只影响绘制图层，
//     障碍/陷阱属于 Tile 级独立字段，必须保持目标原值（粘贴不触发障碍/陷阱绘制）。
bool testMapObstacleTrapEdgeCases()
{
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create obstacle trap edge case temp dir"))
        return false;

    MapEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.resize(900, 650);
    window.show();
    QApplication::processEvents();

    if (!check(window.createNewMap(8, 8), "obstacle trap edge test creates new map"))
        return false;

    MapRenderCanvas* canvas = window.findChild<MapRenderCanvas*>();
    if (!check(canvas != nullptr, "obstacle trap edge test canvas exists"))
        return false;

    canvas->centerOnTile(3, 3);
    QApplication::processEvents();

    bool ok = true;

    auto tileCenter = [&](int x, int y) {
        QPoint center = canvas->tileToScreenCenter(x, y);
        if (!canvas->rect().contains(center))
        {
            canvas->centerOnTile(x, y);
            QApplication::processEvents();
            center = canvas->tileToScreenCenter(x, y);
        }
        return center;
    };

    // 1. 陷阱工具右键拖动连续绘制：从 (2,2) 拖到 (2,4)，每个瓦片都应写入陷阱索引。
    canvas->setEditTool(MapEditTool::TrapPaint);
    canvas->setPaintTrapIndex(9);
    QPoint trapStart = tileCenter(2, 2);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, trapStart, Qt::RightButton, Qt::RightButton);
    QApplication::processEvents();
    QPoint trapMid = tileCenter(2, 3);
    sendMapMouseEvent(*canvas, QEvent::MouseMove, trapMid, Qt::NoButton, Qt::RightButton);
    QApplication::processEvents();
    QPoint trapEnd = tileCenter(2, 4);
    sendMapMouseEvent(*canvas, QEvent::MouseMove, trapEnd, Qt::NoButton, Qt::RightButton);
    QApplication::processEvents();
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, trapEnd, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileTrap(2, 2) == 9,
               "trap right-drag draws start tile (2,2)") && ok;
    ok = check(window.getMapEditor().getTileTrap(2, 3) == 9,
               "trap right-drag draws mid tile (2,3)") && ok;
    ok = check(window.getMapEditor().getTileTrap(2, 4) == 9,
               "trap right-drag draws end tile (2,4)") && ok;

    // 2. 画布缩放后仍能正确命中瓦片：放大后在 (5,5) 右键绘制障碍，
    //    验证 tileToScreenCenter 在缩放变换后仍指向正确瓦片中心。
    float zoomBefore = canvas->getZoomLevel();
    canvas->zoomIn();
    QApplication::processEvents();
    ok = check(canvas->getZoomLevel() > zoomBefore,
               "obstacle trap edge test zoom level increased") && ok;
    canvas->setEditTool(MapEditTool::ObstaclePaint);
    canvas->setPaintObstacle(0x80);
    // 缩放后 (5,5) 可能移出视野，tileCenter 会重新定位画布。
    QPoint tile55 = tileCenter(5, 5);
    ok = check(canvas->rect().contains(tile55),
               "obstacle trap edge test tile center in view after zoom") && ok;
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile55, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile55, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileObstacle(5, 5) == 0x80,
               "obstacle tool right click hits correct tile after zoom") && ok;
    // 缩放后左键拾取也命中同一瓦片。
    int pickedAfterZoom = -1;
    QMetaObject::Connection conn = QObject::connect(canvas, &MapRenderCanvas::obstaclePicked,
        [&pickedAfterZoom](uint8_t obs, int, int) { pickedAfterZoom = obs; });
    canvas->setPaintObstacle(0x40);
    tile55 = tileCenter(5, 5);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, tile55, Qt::LeftButton, Qt::LeftButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, tile55, Qt::LeftButton, Qt::NoButton);
    QApplication::processEvents();
    QObject::disconnect(conn);
    ok = check(pickedAfterZoom == 0x80,
               "obstacle tool left click picks correct tile after zoom") && ok;

    // 3. 区域粘贴不覆盖目标瓦片的障碍/陷阱。
    //    源区 (6,6) 设置图层 + 障碍 0xA0 + 陷阱 4；目标 (0,0) 预置障碍 0x40 + 陷阱 2。
    //    粘贴后目标图层应来自源，但障碍/陷阱必须保持目标原值（粘贴不触发障碍/陷阱绘制）。
    canvas->resetZoom();
    QApplication::processEvents();
    MapTileData srcTile;
    srcTile.layer[0].mpc = 0;
    srcTile.layer[0].frame = 11;
    srcTile.layer[1].mpc = 0;
    srcTile.layer[1].frame = 22;
    window.getMapEditorRef().setTile(6, 6, srcTile);
    window.getMapEditorRef().setTileObstacle(6, 6, 0xA0);
    window.getMapEditorRef().setTileTrap(6, 6, 4);

    MapTileData dstTile;
    dstTile.layer[0].frame = 99;
    window.getMapEditorRef().setTile(0, 0, dstTile);
    window.getMapEditorRef().setTileObstacle(0, 0, 0x40);
    window.getMapEditorRef().setTileTrap(0, 0, 2);

    // 复制源单瓦片，粘贴到 (0,0)。
    canvas->setEditTool(MapEditTool::AreaSelect);
    canvas->copyArea(6, 6, 6, 6, AreaSelectionShape::Rectangle);
    ok = check(canvas->hasClipboardData(),
               "obstacle trap paste test copied source tile to clipboard") && ok;
    canvas->pasteArea(0, 0);
    QApplication::processEvents();

    MapTileData pastedTile = window.getMapEditor().getTile(0, 0);
    // 粘贴覆盖了图层（全部图层模式下源 frame 写入目标）。
    ok = check(pastedTile.layer[0].frame == 11,
               "paste copies tile layer frame from source to target") && ok;
    // 关键断言：障碍/陷阱不被粘贴覆盖，保持目标原值。
    ok = check(window.getMapEditor().getTileObstacle(0, 0) == 0x40,
               "paste does not overwrite target obstacle (paste does not trigger obstacle draw)") && ok;
    ok = check(window.getMapEditor().getTileTrap(0, 0) == 2,
               "paste does not overwrite target trap (paste does not trigger trap draw)") && ok;

    {
        ModalDialogAutoCloser closer;
        window.close();
        QApplication::processEvents();
    }
    return ok;
}

// 剪贴板右键优先级测试：复制区域后切换到障碍/陷阱工具，右键目标瓦片必须绘制
// 障碍/陷阱值，且不应触发区域粘贴（剪贴板里的图层不得覆盖目标图层）。
// 这验证 MapRenderCanvas::mousePressEvent 中 ObstaclePaint/TrapPaint 分支在
// 剪贴板粘贴分支之前 return，确保复制后切工具右键绘制语义符合预期。
bool testMapObstacleTrapClipboardRightClickPriority()
{
    MapEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.resize(900, 650);
    window.show();
    QApplication::processEvents();

    if (!check(window.createNewMap(8, 8), "clipboard priority test creates new map"))
        return false;

    MapRenderCanvas* canvas = window.findChild<MapRenderCanvas*>();
    if (!check(canvas != nullptr, "clipboard priority test canvas exists"))
        return false;

    canvas->centerOnTile(4, 4);
    QApplication::processEvents();

    bool ok = true;

    auto tileCenter = [&](int x, int y) {
        QPoint center = canvas->tileToScreenCenter(x, y);
        if (!canvas->rect().contains(center))
        {
            canvas->centerOnTile(x, y);
            QApplication::processEvents();
            center = canvas->tileToScreenCenter(x, y);
        }
        return center;
    };

    // 准备源瓦片 (1,1)：有显著图层 frame（粘贴会写入此值）。
    MapTileData srcTile;
    srcTile.layer[0].mpc = 0;
    srcTile.layer[0].frame = 77;
    srcTile.layer[1].mpc = 0;
    srcTile.layer[1].frame = 88;
    window.getMapEditorRef().setTile(1, 1, srcTile);

    // 复制源瓦片到剪贴板。
    canvas->setEditTool(MapEditTool::AreaSelect);
    canvas->copyArea(1, 1, 1, 1, AreaSelectionShape::Rectangle);
    ok = check(canvas->hasClipboardData(),
               "clipboard priority test copied source tile to clipboard") && ok;

    // 目标瓦片 (5,5) 预置图层 frame，障碍清零、陷阱清零。
    MapTileData dstTile;
    dstTile.layer[0].frame = 3;
    dstTile.layer[1].frame = 4;
    window.getMapEditorRef().setTile(5, 5, dstTile);
    window.getMapEditorRef().setTileObstacle(5, 5, 0x00);
    window.getMapEditorRef().setTileTrap(5, 5, 0);
    uint8_t dstFrameBefore = window.getMapEditor().getTile(5, 5).layer[0].frame;

    // 切换到障碍工具并右键 (5,5)：应绘制障碍值，不应粘贴剪贴板图层。
    canvas->setEditTool(MapEditTool::ObstaclePaint);
    canvas->setPaintObstacle(0x80);
    // 关键：setEditTool(ObstaclePaint) 会把 pastePreviewVisible 清零。这里强制重新置 true，
    // 模拟"剪贴板预览仍可见且剪贴板存在"的场景。这样若把剪贴板粘贴分支挪到障碍/陷阱
    // 判断之前，右键就会先触发粘贴而非绘制障碍，断言 obstacle==0x80 会失败——测试因此
    // 对 mousePressEvent 中分支顺序真正敏感，能够捕获优先级回归。
    canvas->setPastePreviewVisibleForTest(true);
    QPoint target = tileCenter(5, 5);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, target, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, target, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileObstacle(5, 5) == 0x80,
               "obstacle tool right click draws obstacle even with clipboard present") && ok;
    ok = check(window.getMapEditor().getTile(5, 5).layer[0].frame == dstFrameBefore,
               "obstacle right click does not paste clipboard layer over target") && ok;
    ok = check(canvas->hasClipboardData(),
               "clipboard remains intact after obstacle right click") && ok;

    // 切换到陷阱工具并右键 (4,4)：应绘制陷阱值，不应粘贴剪贴板图层。
    window.getMapEditorRef().setTileObstacle(4, 4, 0x00);
    window.getMapEditorRef().setTileTrap(4, 4, 0);
    MapTileData dst2;
    dst2.layer[0].frame = 5;
    dst2.layer[1].frame = 6;
    window.getMapEditorRef().setTile(4, 4, dst2);
    uint8_t dst2FrameBefore = window.getMapEditor().getTile(4, 4).layer[0].frame;

    canvas->setEditTool(MapEditTool::TrapPaint);
    canvas->setPaintTrapIndex(7);
    // 同障碍阶段：setEditTool(TrapPaint) 清零 pastePreviewVisible，这里强制重新置 true，
    // 确保测试对分支顺序敏感（剪贴板预览可见时陷阱分支仍须优先于粘贴分支）。
    canvas->setPastePreviewVisibleForTest(true);
    QPoint target2 = tileCenter(4, 4);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, target2, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, target2, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    ok = check(window.getMapEditor().getTileTrap(4, 4) == 7,
               "trap tool right click draws trap even with clipboard present") && ok;
    ok = check(window.getMapEditor().getTile(4, 4).layer[0].frame == dst2FrameBefore,
               "trap right click does not paste clipboard layer over target") && ok;

    // 对照：回到 TilePaint 工具右键目标瓦片，此时剪贴板存在，应触发区域粘贴
    // （图层被源值覆盖），证明优先级分流正确——不是所有工具都被障碍/陷阱拦截。
    // 注意：障碍/陷阱工具的左键拾取与左键绘制会把 pastePreviewVisible 置 false，
    // 因此对照前重新 copyArea（copyArea 会把 pastePreviewVisible 重置为 true），
    // 保证 TilePaint 右键能进入剪贴板粘贴分支，验证优先级分流确实发生。
    MapTileData dst3;
    dst3.layer[0].frame = 13;
    window.getMapEditorRef().setTile(6, 6, dst3);
    canvas->setEditTool(MapEditTool::AreaSelect);
    canvas->copyArea(1, 1, 1, 1, AreaSelectionShape::Rectangle);
    canvas->setEditTool(MapEditTool::TilePaint);
    QPoint target3 = tileCenter(6, 6);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonPress, target3, Qt::RightButton, Qt::RightButton);
    sendMapMouseEvent(*canvas, QEvent::MouseButtonRelease, target3, Qt::RightButton, Qt::NoButton);
    QApplication::processEvents();
    // 全图层模式下 TilePaint 右键粘贴会用剪贴板源 frame 77 覆盖目标 frame。
    // 单图层默认 paintLayer=0，正好覆盖 layer 0 frame 为源值 77。
    uint8_t dst3FrameAfter = window.getMapEditor().getTile(6, 6).layer[0].frame;
    bool pasteOccurred = (dst3FrameAfter == 77);
    ok = check(pasteOccurred,
               "tile tool right click pastes clipboard when not on obstacle/trap tool") && ok;

    {
        ModalDialogAutoCloser closer;
        window.close();
        QApplication::processEvents();
    }
    return ok;
}

// 测试 Joystick 旧 Image 双帧模式读取和预览。
// 运行时 Joystick::initFromIni 在没有 BaseImage/ThumbImage 时，
// 读取 Image 并拆分为 frame 0（背景）和 frame 1（摇杆头）。
bool testMenuEditorJoystickLegacyImageDualFrame()
{
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create joystick legacy image temp dir"))
        return false;

    QDir root(tempDir.path());
    root.mkpath("images");

    const QString menuPath = root.filePath("joystick.menu.ini");
    const QString windowPath = root.filePath("window.ini");
    const QString joystickPath = root.filePath("joystick.ini");
    bool ok = true;

    ok = check(writeUtf8TextFile(menuPath,
        "[menu]\n"
        "name=JoystickPanel\n"
        "window=window.ini\n"
        "\n"
        "[component1]\n"
        "type=Joystick\n"
        "name=joystick\n"
        "file=joystick.ini\n"),
        "write joystick legacy menu definition") && ok;
    ok = check(writeUtf8TextFile(windowPath,
        "[init]\n"
        "width=200\n"
        "height=160\n"),
        "write joystick legacy menu window") && ok;

    // 旧格式：只有 Image 字段，没有 BaseImage/ThumbImage
    ok = check(writeUtf8TextFile(joystickPath,
        "[init]\n"
        "left=10\n"
        "top=20\n"
        "width=100\n"
        "height=100\n"
        "range=100\n"
        "image=images/joystick.img\n"
        "; legacy joystick comment to preserve\n"),
        "write joystick legacy component definition") && ok;

    if (!ok)
        return false;

    MenuEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.setAssetsBasePath(root.path());
    window.openMenuDefinition(menuPath);
    window.show();
    QApplication::processEvents();

    QTreeWidget* componentTree = window.findChild<QTreeWidget*>("componentTree");
    QLineEdit* imageEdit = window.findChild<QLineEdit*>("imageEdit");
    QLineEdit* baseImageEdit = window.findChild<QLineEdit*>("joystickBaseImageEdit");
    QLineEdit* thumbImageEdit = window.findChild<QLineEdit*>("joystickThumbImageEdit");
    QSpinBox* rangeSpin = window.findChild<QSpinBox*>("rangeSpin");
    if (!check(componentTree != nullptr && imageEdit != nullptr &&
               baseImageEdit != nullptr && thumbImageEdit != nullptr && rangeSpin != nullptr,
               "joystick legacy editor controls exist"))
    {
        return false;
    }

    componentTree->setCurrentItem(componentTree->topLevelItem(1));
    QApplication::processEvents();

    // 旧格式 Image 应该被读取到 image 字段
    ok = check(imageEdit->text() == "images/joystick.img",
               "joystick legacy editor loads Image field") && ok;
    // BaseImage/ThumbImage 应为空（旧格式没有这些字段）
    ok = check(baseImageEdit->text().isEmpty(),
               "joystick legacy editor leaves BaseImage empty for old format") && ok;
    ok = check(thumbImageEdit->text().isEmpty(),
               "joystick legacy editor leaves ThumbImage empty for old format") && ok;
    ok = check(rangeSpin->value() == 100,
               "joystick legacy editor loads range") && ok;

    // 保存后应保留 Image 字段和注释，不添加 BaseImage/ThumbImage
    bool invoked = QMetaObject::invokeMethod(&window, "onSaveFile", Qt::DirectConnection);
    ok = check(invoked, "save joystick legacy menu definition") && ok;

    const QString joystickText = readUtf8TextFile(joystickPath);
    ok = check(joystickText.contains("image=images/joystick.img"),
               "joystick legacy save preserves Image field") && ok;
    ok = check(!joystickText.contains("baseimage="),
               "joystick legacy save does not add BaseImage when empty") && ok;
    ok = check(!joystickText.contains("thumbimage="),
               "joystick legacy save does not add ThumbImage when empty") && ok;
    ok = check(joystickText.contains("; legacy joystick comment to preserve"),
               "joystick legacy save preserves comments") && ok;

    window.close();
    QApplication::processEvents();
    return ok;
}

// 测试 Joystick 只设置 BaseImage（无 ThumbImage）时的行为。
// 运行时 Joystick::initFromIni 在 BaseImage 或 ThumbImage 任一非空时，
// 都会走新格式分支，loadRes 空字符串会返回 nullptr 并记录日志。
bool testMenuEditorJoystickSingleBaseImageOnly()
{
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create joystick single base image temp dir"))
        return false;

    QDir root(tempDir.path());
    root.mkpath("images");

    const QString menuPath = root.filePath("joystick.menu.ini");
    const QString windowPath = root.filePath("window.ini");
    const QString joystickPath = root.filePath("joystick.ini");
    bool ok = true;

    ok = check(writeUtf8TextFile(menuPath,
        "[menu]\n"
        "name=JoystickPanel\n"
        "window=window.ini\n"
        "\n"
        "[component1]\n"
        "type=Joystick\n"
        "name=joystick\n"
        "file=joystick.ini\n"),
        "write joystick single base menu definition") && ok;
    ok = check(writeUtf8TextFile(windowPath,
        "[init]\n"
        "width=200\n"
        "height=160\n"),
        "write joystick single base menu window") && ok;

    // 只有 BaseImage，没有 ThumbImage
    ok = check(writeUtf8TextFile(joystickPath,
        "[init]\n"
        "left=10\n"
        "top=20\n"
        "width=100\n"
        "height=100\n"
        "range=100\n"
        "baseimage=images/base.png\n"),
        "write joystick single base component definition") && ok;

    QImage baseImage(100, 100, QImage::Format_ARGB32);
    baseImage.fill(QColor(220, 30, 30));
    ok = check(baseImage.save(root.filePath("images/base.png")),
               "save joystick single base image") && ok;
    if (!ok)
        return false;

    MenuEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.setAssetsBasePath(root.path());
    window.openMenuDefinition(menuPath);
    window.show();
    QApplication::processEvents();

    QTreeWidget* componentTree = window.findChild<QTreeWidget*>("componentTree");
    QLineEdit* baseImageEdit = window.findChild<QLineEdit*>("joystickBaseImageEdit");
    QLineEdit* thumbImageEdit = window.findChild<QLineEdit*>("joystickThumbImageEdit");
    if (!check(componentTree != nullptr && baseImageEdit != nullptr && thumbImageEdit != nullptr,
               "joystick single base editor controls exist"))
    {
        return false;
    }

    componentTree->setCurrentItem(componentTree->topLevelItem(1));
    QApplication::processEvents();

    ok = check(baseImageEdit->text() == "images/base.png",
               "joystick single base editor loads BaseImage") && ok;
    ok = check(thumbImageEdit->text().isEmpty(),
               "joystick single base editor leaves ThumbImage empty") && ok;

    // 保存后应保留 BaseImage，不添加 ThumbImage
    bool invoked = QMetaObject::invokeMethod(&window, "onSaveFile", Qt::DirectConnection);
    ok = check(invoked, "save joystick single base menu definition") && ok;

    const QString joystickText = readUtf8TextFile(joystickPath);
    ok = check(joystickText.contains("baseimage=images/base.png"),
               "joystick single base save preserves BaseImage") && ok;
    ok = check(!joystickText.contains("thumbimage="),
               "joystick single base save does not add empty ThumbImage") && ok;

    window.close();
    QApplication::processEvents();
    return ok;
}

// 测试子菜单中的 Joystick 走相同逻辑。
// JoystickPanel 运行时通过 ConfigDrivenPanel::loadMenuDefinition 加载 joystick.menu.ini，
// 子菜单中的 Joystick 也应通过相同的 INI 契约加载。
bool testMenuEditorJoystickInSubmenuConsistency()
{
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create joystick submenu temp dir"))
        return false;

    QDir root(tempDir.path());
    root.mkpath("images");

    const QString menuPath = root.filePath("main.menu.ini");
    const QString windowPath = root.filePath("window.ini");
    const QString subMenuPath = root.filePath("sub.menu.ini");
    const QString subWindowPath = root.filePath("sub_window.ini");
    const QString joystickPath = root.filePath("joystick.ini");
    bool ok = true;

    ok = check(writeUtf8TextFile(menuPath,
        "[menu]\n"
        "name=Main\n"
        "window=window.ini\n"
        "\n"
        "[submenu1]\n"
        "name=Sub\n"
        "file=sub.menu.ini\n"),
        "write joystick submenu main menu definition") && ok;
    ok = check(writeUtf8TextFile(windowPath,
        "[init]\n"
        "width=200\n"
        "height=160\n"),
        "write joystick submenu main window") && ok;
    ok = check(writeUtf8TextFile(subMenuPath,
        "[menu]\n"
        "name=Sub\n"
        "window=sub_window.ini\n"
        "\n"
        "[component1]\n"
        "type=Joystick\n"
        "name=joystick\n"
        "file=joystick.ini\n"),
        "write joystick submenu definition") && ok;
    ok = check(writeUtf8TextFile(subWindowPath,
        "[init]\n"
        "width=200\n"
        "height=160\n"),
        "write joystick submenu window") && ok;
    ok = check(writeUtf8TextFile(joystickPath,
        "[init]\n"
        "left=10\n"
        "top=20\n"
        "width=100\n"
        "height=100\n"
        "range=80\n"
        "baseimage=images/base.png\n"
        "thumbimage=images/thumb.png\n"),
        "write joystick submenu component definition") && ok;

    QImage baseImage(100, 100, QImage::Format_ARGB32);
    baseImage.fill(QColor(220, 30, 30));
    QImage thumbImage(20, 20, QImage::Format_ARGB32);
    thumbImage.fill(QColor(30, 220, 30));
    ok = check(baseImage.save(root.filePath("images/base.png")),
               "save joystick submenu base image") && ok;
    ok = check(thumbImage.save(root.filePath("images/thumb.png")),
               "save joystick submenu thumb image") && ok;
    if (!ok)
        return false;

    MenuEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.setAssetsBasePath(root.path());
    window.openMenuDefinition(menuPath);
    window.show();
    QApplication::processEvents();

    QTreeWidget* componentTree = window.findChild<QTreeWidget*>("componentTree");
    if (!check(componentTree != nullptr, "joystick submenu component tree exists"))
        return false;

    // 子菜单组件在树中位于主菜单组件之后
    int topLevelCount = componentTree->topLevelItemCount();
    // 找到子菜单节点并展开
    QTreeWidgetItem* subMenuNode = nullptr;
    for (int i = 0; i < topLevelCount; i++)
    {
        QTreeWidgetItem* item = componentTree->topLevelItem(i);
        if (item->text(0) == "SubMenu" || item->childCount() > 0)
        {
            subMenuNode = item;
            break;
        }
    }
    ok = check(subMenuNode != nullptr, "joystick submenu node found in tree") && ok;
    if (!ok)
    {
        window.close();
        return false;
    }

    // 展开子菜单并选中 Joystick 组件
    componentTree->expandItem(subMenuNode);
    QApplication::processEvents();

    QTreeWidgetItem* joystickItem = nullptr;
    for (int i = 0; i < subMenuNode->childCount(); i++)
    {
        QTreeWidgetItem* child = subMenuNode->child(i);
        if (child->text(0) == "Joystick")
        {
            joystickItem = child;
            break;
        }
    }
    ok = check(joystickItem != nullptr, "joystick submenu component found") && ok;
    if (!ok)
    {
        window.close();
        return false;
    }

    componentTree->setCurrentItem(joystickItem);
    QApplication::processEvents();

    QLineEdit* baseImageEdit = window.findChild<QLineEdit*>("joystickBaseImageEdit");
    QLineEdit* thumbImageEdit = window.findChild<QLineEdit*>("joystickThumbImageEdit");
    QSpinBox* rangeSpin = window.findChild<QSpinBox*>("rangeSpin");
    ok = check(baseImageEdit != nullptr && thumbImageEdit != nullptr && rangeSpin != nullptr,
               "joystick submenu property editor controls exist") && ok;
    if (!ok)
    {
        window.close();
        return false;
    }

    // 子菜单中的 Joystick 应读取相同的字段
    ok = check(baseImageEdit->text() == "images/base.png",
               "joystick submenu editor loads BaseImage") && ok;
    ok = check(thumbImageEdit->text() == "images/thumb.png",
               "joystick submenu editor loads ThumbImage") && ok;
    ok = check(rangeSpin->value() == 80,
               "joystick submenu editor loads range") && ok;

    // 保存后字段应保留
    bool invoked = QMetaObject::invokeMethod(&window, "onSaveFile", Qt::DirectConnection);
    ok = check(invoked, "save joystick submenu menu definition") && ok;

    const QString joystickText = readUtf8TextFile(joystickPath);
    ok = check(joystickText.contains("baseimage=images/base.png"),
               "joystick submenu save preserves BaseImage") && ok;
    ok = check(joystickText.contains("thumbimage=images/thumb.png"),
               "joystick submenu save preserves ThumbImage") && ok;
    ok = check(joystickText.contains("range=80"),
               "joystick submenu save preserves range") && ok;

    window.close();
    QApplication::processEvents();
    return ok;
}

// 测试 Button 派生类型的 stretch 保存和运行时默认值一致性。
// 覆盖：false→true、true→false、缺省默认值、多类型（Button/TextButton/RoundButton/ChooseTextButton/DragRoundButton）。
bool testMenuEditorButtonStretchPreservation()
{
    struct StretchTestCase
    {
        const char* type;
        bool runtimeDefault;
    };
    const StretchTestCase cases[] = {
        {"Button", false},
        {"TextButton", true},
        {"RoundButton", true},
        {"ChooseTextButton", true},
        {"DragRoundButton", true},
        {"DragButton", false},
    };

    bool ok = true;

    for (const auto& tc : cases)
    {
        QTemporaryDir tempDir;
        if (!check(tempDir.isValid(), "create stretch temp dir"))
            return false;

        QDir root(tempDir.path());
        const QString menuPath = root.filePath("main.menu.ini");
        const QString windowPath = root.filePath("window.ini");
        const QString compPath = root.filePath("comp.ini");

        ok = check(writeUtf8TextFile(menuPath,
            QString("[menu]\n"
                    "name=Main\n"
                    "window=window.ini\n"
                    "\n"
                    "[component1]\n"
                    "type=%1\n"
                    "name=comp\n"
                    "file=comp.ini\n").arg(tc.type)),
            QString("write %1 stretch menu definition").arg(tc.type)) && ok;
        ok = check(writeUtf8TextFile(windowPath,
            "[init]\n"
            "width=200\n"
            "height=160\n"),
            QString("write %1 stretch menu window").arg(tc.type)) && ok;

        // 测试 1: 缺省 Stretch（INI 无 stretch 字段）→ 编辑器应显示运行时默认值
        ok = check(writeUtf8TextFile(compPath,
            "[init]\n"
            "left=10\n"
            "top=20\n"
            "width=80\n"
            "height=24\n"
            "image=image/comp.img\n"),
            QString("write %1 stretch default component").arg(tc.type)) && ok;
        if (!ok) continue;

        {
            MenuEditorWindow window;
            window.setAttribute(Qt::WA_DontShowOnScreen, true);
            window.setAssetsBasePath(root.path());
            window.openMenuDefinition(menuPath);
            window.show();
            QApplication::processEvents();

            QTreeWidget* componentTree = window.findChild<QTreeWidget*>("componentTree");
            QCheckBox* stretchCheck = window.findChild<QCheckBox*>("stretchCheck");
            if (!check(componentTree != nullptr && stretchCheck != nullptr,
                       QString("%1 stretch default controls exist").arg(tc.type)))
            {
                ok = false;
                window.close();
                QApplication::processEvents();
                continue;
            }

            componentTree->setCurrentItem(componentTree->topLevelItem(1));
            QApplication::processEvents();

            // 缺省时应显示运行时默认值
            ok = check(stretchCheck->isChecked() == tc.runtimeDefault,
                       QString("%1 stretch default=%2 matches runtime")
                           .arg(tc.type).arg(tc.runtimeDefault)) && ok;

            // 触发一次修改以确保组件进入 modifiedComponentInis（保存只会写出已修改的组件 INI）。
            // 先切换到相反值再切回，保证 toggled 信号被触发。
            stretchCheck->setChecked(!tc.runtimeDefault);
            QApplication::processEvents();
            stretchCheck->setChecked(tc.runtimeDefault);
            QApplication::processEvents();

            // 保存后应写出运行时默认值（true/false）
            bool invoked = QMetaObject::invokeMethod(&window, "onSaveFile", Qt::DirectConnection);
            ok = check(invoked, QString("save %1 stretch default").arg(tc.type)) && ok;

            const QString compText = readUtf8TextFile(compPath);
            QString expectedStretch = tc.runtimeDefault ? "stretch=true" : "stretch=false";
            ok = check(compText.contains(expectedStretch),
                       QString("%1 stretch default save writes %2")
                           .arg(tc.type).arg(expectedStretch)) && ok;

            window.close();
            QApplication::processEvents();
        }

        // 测试 2: true→false（INI 有 stretch=true，修改为 false，保存后验证）
        ok = check(writeUtf8TextFile(compPath,
            "[init]\n"
            "left=10\n"
            "top=20\n"
            "width=80\n"
            "height=24\n"
            "image=image/comp.img\n"
            "stretch=true\n"),
            QString("write %1 stretch true→false component").arg(tc.type)) && ok;
        if (!ok) continue;

        {
            MenuEditorWindow window;
            window.setAttribute(Qt::WA_DontShowOnScreen, true);
            window.setAssetsBasePath(root.path());
            window.openMenuDefinition(menuPath);
            window.show();
            QApplication::processEvents();

            QTreeWidget* componentTree = window.findChild<QTreeWidget*>("componentTree");
            QCheckBox* stretchCheck = window.findChild<QCheckBox*>("stretchCheck");
            componentTree->setCurrentItem(componentTree->topLevelItem(1));
            QApplication::processEvents();

            ok = check(stretchCheck->isChecked(),
                       QString("%1 stretch true→false loads stretch=true").arg(tc.type)) && ok;

            // 修改为 false
            stretchCheck->setChecked(false);
            QApplication::processEvents();

            bool invoked = QMetaObject::invokeMethod(&window, "onSaveFile", Qt::DirectConnection);
            ok = check(invoked, QString("save %1 stretch true→false").arg(tc.type)) && ok;

            const QString compText = readUtf8TextFile(compPath);
            ok = check(compText.contains("stretch=false"),
                       QString("%1 stretch true→false save writes stretch=false").arg(tc.type)) && ok;
            ok = check(!compText.contains("stretch=true"),
                       QString("%1 stretch true→false save removes stretch=true").arg(tc.type)) && ok;

            window.close();
            QApplication::processEvents();
        }

        // 测试 3: false→true（INI 有 stretch=false，修改为 true，保存后验证）
        ok = check(writeUtf8TextFile(compPath,
            "[init]\n"
            "left=10\n"
            "top=20\n"
            "width=80\n"
            "height=24\n"
            "image=image/comp.img\n"
            "stretch=false\n"),
            QString("write %1 stretch false→true component").arg(tc.type)) && ok;
        if (!ok) continue;

        {
            MenuEditorWindow window;
            window.setAttribute(Qt::WA_DontShowOnScreen, true);
            window.setAssetsBasePath(root.path());
            window.openMenuDefinition(menuPath);
            window.show();
            QApplication::processEvents();

            QTreeWidget* componentTree = window.findChild<QTreeWidget*>("componentTree");
            QCheckBox* stretchCheck = window.findChild<QCheckBox*>("stretchCheck");
            componentTree->setCurrentItem(componentTree->topLevelItem(1));
            QApplication::processEvents();

            ok = check(!stretchCheck->isChecked(),
                       QString("%1 stretch false→true loads stretch=false").arg(tc.type)) && ok;

            // 修改为 true
            stretchCheck->setChecked(true);
            QApplication::processEvents();

            bool invoked = QMetaObject::invokeMethod(&window, "onSaveFile", Qt::DirectConnection);
            ok = check(invoked, QString("save %1 stretch false→true").arg(tc.type)) && ok;

            const QString compText = readUtf8TextFile(compPath);
            ok = check(compText.contains("stretch=true"),
                       QString("%1 stretch false→true save writes stretch=true").arg(tc.type)) && ok;
            ok = check(!compText.contains("stretch=false"),
                       QString("%1 stretch false→true save removes stretch=false").arg(tc.type)) && ok;

            window.close();
            QApplication::processEvents();
        }
    }

    return ok;
}

// 测试 Joystick 预览的背景图拉伸行为。
// 运行时 Joystick 继承 RoundButton（stretch=true），且 initFromIni 不读取 Stretch 字段，
// 因此背景图总是拉伸到组件区域。本测试使用 40x40 的非正方形背景图配 100x100 组件区域，
// 通过检查区域边缘像素来区分"拉伸"与"原尺寸绘制/居中"。
// 若渲染未拉伸（原尺寸绘制在左上角），40x40 图只覆盖 (30,40)-(70,80) 画布坐标，
// 右下角 (125,135) 处不会是背景图颜色。
bool testMenuEditorJoystickStretchPreview()
{
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create joystick stretch preview temp dir"))
        return false;

    QDir root(tempDir.path());
    root.mkpath("images");

    const QString menuPath = root.filePath("joystick.menu.ini");
    const QString windowPath = root.filePath("window.ini");
    const QString joystickPath = root.filePath("joystick.ini");
    bool ok = true;

    ok = check(writeUtf8TextFile(menuPath,
        "[menu]\n"
        "name=JoystickPanel\n"
        "window=window.ini\n"
        "\n"
        "[component1]\n"
        "type=Joystick\n"
        "name=joystick\n"
        "file=joystick.ini\n"),
        "write joystick stretch preview menu definition") && ok;
    ok = check(writeUtf8TextFile(windowPath,
        "[init]\n"
        "width=200\n"
        "height=160\n"),
        "write joystick stretch preview menu window") && ok;

    // 组件区域 100x100，但背景图只有 40x40。
    // 若不拉伸，40x40 图只覆盖组件左上角的一小块。
    ok = check(writeUtf8TextFile(joystickPath,
        "[init]\n"
        "left=10\n"
        "top=20\n"
        "width=100\n"
        "height=100\n"
        "range=100\n"
        "baseimage=images/base.png\n"),
        "write joystick stretch preview component definition") && ok;

    QImage baseImage(40, 40, QImage::Format_ARGB32);
    baseImage.fill(QColor(220, 30, 30));
    ok = check(baseImage.save(root.filePath("images/base.png")),
               "save joystick stretch preview base image") && ok;
    if (!ok)
        return false;

    MenuEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.setAssetsBasePath(root.path());
    window.openMenuDefinition(menuPath);
    window.show();
    QApplication::processEvents();

    QTreeWidget* componentTree = window.findChild<QTreeWidget*>("componentTree");
    MenuPreviewCanvas* previewCanvas = window.findChild<MenuPreviewCanvas*>();
    if (!check(componentTree != nullptr && previewCanvas != nullptr,
               "joystick stretch preview controls exist"))
    {
        return false;
    }

    componentTree->setCurrentItem(componentTree->topLevelItem(1));
    QApplication::processEvents();

    QImage previewImage(previewCanvas->size(), QImage::Format_ARGB32);
    previewImage.fill(Qt::transparent);
    previewCanvas->render(&previewImage);

    // 画布有 (20,20) 偏移，scaleFactor=1.0。
    // 组件 INI 区域 (10,20)-(110,120) → 画布区域 (30,40)-(130,140)。
    const QColor bgColor(48, 48, 48);

    // 1. 左上角附近（INI 15,25 → 画布 35,45）：无论是否拉伸都应被背景图覆盖。
    ok = check(previewImage.pixelColor(35, 45).red() > 180,
               "joystick stretch preview covers top-left of rect") && ok;

    // 2. 右下角附近（INI 105,115 → 画布 125,135）：
    //    拉伸时此处应为背景图红色；不拉伸时（40x40 原尺寸绘制在左上角）此处应为画布背景色。
    QColor bottomRightColor = previewImage.pixelColor(125, 135);
    ok = check(bottomRightColor.red() > 180,
               "joystick stretch preview stretches base image to bottom-right corner") && ok;
    ok = check(bottomRightColor != bgColor,
               "joystick stretch preview bottom-right is not canvas background (proves stretch)") && ok;

    // 3. 组件区域外（INI 115,125 → 画布 135,145）：不应被背景图覆盖。
    QColor outsideColor = previewImage.pixelColor(135, 145);
    ok = check(outsideColor.red() < 180,
               "joystick stretch preview does not paint outside component rect") && ok;

    window.close();
    QApplication::processEvents();
    return ok;
}

// 测试 Stretch 状态在切换组件后保持不丢失。
// 修复前：getProperties() 不设置 stretchSet，切换组件再切回后，
// 显式 stretch=false 会被 resolveStretch 当作"INI 无字段"回退到运行时默认值 true。
// 关键流程：选中 → 修改属性触发 getProperties() → 切走 → 切回 → 检查 Stretch → 保存。
// 旧实现中 getProperties() 不设 stretchSet，切回后 setProperties() 会回退到运行时默认 true。
bool testMenuEditorStretchStateSurvivesComponentSwitch()
{
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create stretch state survival temp dir"))
        return false;

    QDir root(tempDir.path());
    const QString menuPath = root.filePath("main.menu.ini");
    const QString windowPath = root.filePath("window.ini");
    const QString textButtonPath = root.filePath("textbtn.ini");
    const QString buttonPath = root.filePath("btn.ini");
    bool ok = true;

    // 菜单包含两个组件：TextButton（显式 stretch=false）和 Button（缺省 stretch）
    ok = check(writeUtf8TextFile(menuPath,
        "[menu]\n"
        "name=Main\n"
        "window=window.ini\n"
        "\n"
        "[component1]\n"
        "type=TextButton\n"
        "name=textbtn\n"
        "file=textbtn.ini\n"
        "\n"
        "[component2]\n"
        "type=Button\n"
        "name=btn\n"
        "file=btn.ini\n"),
        "write stretch state survival menu definition") && ok;
    ok = check(writeUtf8TextFile(windowPath,
        "[init]\n"
        "width=200\n"
        "height=160\n"),
        "write stretch state survival menu window") && ok;

    // TextButton 运行时默认 stretch=true，但 INI 显式设为 false
    ok = check(writeUtf8TextFile(textButtonPath,
        "[init]\n"
        "left=10\n"
        "top=20\n"
        "width=80\n"
        "height=24\n"
        "image=image/text.img\n"
        "stretch=false\n"),
        "write stretch state survival TextButton definition") && ok;
    ok = check(writeUtf8TextFile(buttonPath,
        "[init]\n"
        "left=100\n"
        "top=20\n"
        "width=80\n"
        "height=24\n"
        "image=image/btn.img\n"),
        "write stretch state survival Button definition") && ok;
    if (!ok)
        return false;

    MenuEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.setAssetsBasePath(root.path());
    window.openMenuDefinition(menuPath);
    window.show();
    QApplication::processEvents();

    QTreeWidget* componentTree = window.findChild<QTreeWidget*>("componentTree");
    QCheckBox* stretchCheck = window.findChild<QCheckBox*>("stretchCheck");
    QSpinBox* widthSpin = window.findChild<QSpinBox*>("widthSpin");
    if (!check(componentTree != nullptr && stretchCheck != nullptr && widthSpin != nullptr,
               "stretch state survival controls exist"))
    {
        return false;
    }

    // 1. 选中 TextButton（topLevelItem(1)），初次从 INI 加载，应显示 stretch=false
    componentTree->setCurrentItem(componentTree->topLevelItem(1));
    QApplication::processEvents();
    ok = check(!stretchCheck->isChecked(),
               "TextButton with explicit stretch=false shows false on first select") && ok;

    // 2. 修改 width 触发 onPropertyChanged → getProperties() → modifiedComponentInis。
    //    这一步是关键：旧实现中 getProperties() 不设 stretchSet，
    //    modifiedComponentInis 中存储的 props.stretchSet=false。
    widthSpin->setValue(120);
    QApplication::processEvents();

    // 3. 切换到 Button（topLevelItem(2)）
    componentTree->setCurrentItem(componentTree->topLevelItem(2));
    QApplication::processEvents();
    ok = check(!stretchCheck->isChecked(),
               "Button with default stretch shows false") && ok;

    // 4. 切回 TextButton（topLevelItem(1)），从 modifiedComponentInis 重新加载。
    //    旧实现：stretchSet=false → setProperties() 回退到运行时默认 true（BUG）。
    //    修复后：stretchSet=true → setProperties() 使用 stretch=false（正确）。
    componentTree->setCurrentItem(componentTree->topLevelItem(1));
    QApplication::processEvents();
    ok = check(!stretchCheck->isChecked(),
               "TextButton stretch=false survives modify+switch+back (not reset to runtime default true)") && ok;

    // 5. 保存，验证 stretch=false 仍被写出（没有被回退为 true）
    bool invoked = QMetaObject::invokeMethod(&window, "onSaveFile", Qt::DirectConnection);
    ok = check(invoked, "save stretch state survival menu definition") && ok;

    const QString textButtonText = readUtf8TextFile(textButtonPath);
    ok = check(textButtonText.contains("stretch=false"),
               "TextButton stretch=false preserved after modify+switch+back+save") && ok;
    ok = check(!textButtonText.contains("stretch=true"),
               "TextButton stretch=false not overwritten to true after modify+switch+back+save") && ok;
    ok = check(textButtonText.contains("width=120"),
               "TextButton width change saved correctly") && ok;

    window.close();
    QApplication::processEvents();
    return ok;
}

// 测试 MemoText 字体默认值和显式值保持。
// 修复前：编辑器全局默认 font=18，但运行时 MemoText 默认 16。
// 修复后：MemoText 缺省时显示 16，显式值（含 0）不被覆盖，切换组件后保持。
// 关键流程：选中 → 修改属性触发 getProperties() → 切走 → 切回 → 检查 font → 保存。
// 旧实现中 getProperties() 不设 fontSet，切回后 setProperties() 会回退到运行时默认 16。
bool testMenuEditorMemoTextFontDefaultAndPreservation()
{
    QTemporaryDir tempDir;
    if (!check(tempDir.isValid(), "create MemoText font temp dir"))
        return false;

    QDir root(tempDir.path());
    const QString menuPath = root.filePath("main.menu.ini");
    const QString windowPath = root.filePath("window.ini");
    const QString memoDefaultPath = root.filePath("memo_default.ini");
    const QString memoExplicitPath = root.filePath("memo_explicit.ini");
    const QString memoZeroPath = root.filePath("memo_zero.ini");
    bool ok = true;

    // 四个组件：MemoText 缺省 font、MemoText 显式 font=25、MemoText 显式 font=0、Button
    ok = check(writeUtf8TextFile(menuPath,
        "[menu]\n"
        "name=Main\n"
        "window=window.ini\n"
        "\n"
        "[component1]\n"
        "type=MemoText\n"
        "name=memoDefault\n"
        "file=memo_default.ini\n"
        "\n"
        "[component2]\n"
        "type=MemoText\n"
        "name=memoExplicit\n"
        "file=memo_explicit.ini\n"
        "\n"
        "[component3]\n"
        "type=MemoText\n"
        "name=memoZero\n"
        "file=memo_zero.ini\n"
        "\n"
        "[component4]\n"
        "type=Button\n"
        "name=btn\n"
        "file=btn.ini\n"),
        "write MemoText font menu definition") && ok;
    ok = check(writeUtf8TextFile(windowPath,
        "[init]\n"
        "width=200\n"
        "height=160\n"),
        "write MemoText font menu window") && ok;

    // MemoText 缺省 font（INI 无 font 字段）
    ok = check(writeUtf8TextFile(memoDefaultPath,
        "[init]\n"
        "left=10\n"
        "top=20\n"
        "width=80\n"
        "height=24\n"
        "image=image/memo1.img\n"),
        "write MemoText default font component") && ok;

    // MemoText 显式 font=25
    ok = check(writeUtf8TextFile(memoExplicitPath,
        "[init]\n"
        "left=10\n"
        "top=60\n"
        "width=80\n"
        "height=24\n"
        "image=image/memo2.img\n"
        "font=25\n"),
        "write MemoText explicit font=25 component") && ok;

    // MemoText 显式 font=0（边界值，不应被覆盖为默认 16）
    ok = check(writeUtf8TextFile(memoZeroPath,
        "[init]\n"
        "left=10\n"
        "top=100\n"
        "width=80\n"
        "height=24\n"
        "image=image/memo3.img\n"
        "font=0\n"),
        "write MemoText explicit font=0 component") && ok;

    // Button 组件（用于切换测试）
    ok = check(writeUtf8TextFile(root.filePath("btn.ini"),
        "[init]\n"
        "left=10\n"
        "top=140\n"
        "width=80\n"
        "height=24\n"
        "image=image/btn.img\n"),
        "write MemoText font Button component") && ok;
    if (!ok)
        return false;

    MenuEditorWindow window;
    window.setAttribute(Qt::WA_DontShowOnScreen, true);
    window.setAssetsBasePath(root.path());
    window.openMenuDefinition(menuPath);
    window.show();
    QApplication::processEvents();

    QTreeWidget* componentTree = window.findChild<QTreeWidget*>("componentTree");
    QSpinBox* labelFontSpin = window.findChild<QSpinBox*>("labelFontSpin");
    QSpinBox* widthSpin = window.findChild<QSpinBox*>("widthSpin");
    if (!check(componentTree != nullptr && labelFontSpin != nullptr && widthSpin != nullptr,
               "MemoText font editor controls exist"))
    {
        return false;
    }

    // 1. 选中缺省 font 的 MemoText，应显示 16（运行时默认）
    componentTree->setCurrentItem(componentTree->topLevelItem(1));
    QApplication::processEvents();
    ok = check(labelFontSpin->value() == 16,
               "MemoText default font=16 matches runtime default") && ok;

    // 2. 选中显式 font=25 的 MemoText，初次从 INI 加载应显示 25
    componentTree->setCurrentItem(componentTree->topLevelItem(2));
    QApplication::processEvents();
    ok = check(labelFontSpin->value() == 25,
               "MemoText explicit font=25 loaded correctly") && ok;

    // 3. 修改 width 触发 onPropertyChanged → getProperties() → modifiedComponentInis。
    //    关键：旧实现中 getProperties() 不设 fontSet，modifiedComponentInis 中 fontSet=false。
    widthSpin->setValue(100);
    QApplication::processEvents();

    // 4. 切换到 Button（topLevelItem(4)）
    componentTree->setCurrentItem(componentTree->topLevelItem(4));
    QApplication::processEvents();

    // 5. 切回 MemoText font=25（topLevelItem(2)），从 modifiedComponentInis 重新加载。
    //    旧实现：fontSet=false → setProperties() 回退到运行时默认 16（BUG）。
    //    修复后：fontSet=true → setProperties() 使用 font=25（正确）。
    componentTree->setCurrentItem(componentTree->topLevelItem(2));
    QApplication::processEvents();
    ok = check(labelFontSpin->value() == 25,
               "MemoText font=25 survives modify+switch+back (not reset to runtime default 16)") && ok;

    // 6. 保存，验证 font=25 不被覆盖
    bool invoked = QMetaObject::invokeMethod(&window, "onSaveFile", Qt::DirectConnection);
    ok = check(invoked, "save MemoText font preservation") && ok;

    const QString memoExplicitText = readUtf8TextFile(memoExplicitPath);
    ok = check(memoExplicitText.contains("font=25"),
               "MemoText font=25 preserved after modify+switch+back+save") && ok;
    ok = check(!memoExplicitText.contains("font=16") && !memoExplicitText.contains("font=18"),
               "MemoText font=25 not overwritten to default after modify+switch+back+save") && ok;

    // 7. 测试显式 font=0 场景：选中 → 修改属性 → 切走 → 切回 → 检查 → 保存
    componentTree->setCurrentItem(componentTree->topLevelItem(3));
    QApplication::processEvents();
    ok = check(labelFontSpin->value() == 0,
               "MemoText explicit font=0 loaded correctly") && ok;

    // 修改 width 触发 getProperties()
    widthSpin->setValue(90);
    QApplication::processEvents();

    // 切换到 Button 再切回
    componentTree->setCurrentItem(componentTree->topLevelItem(4));
    QApplication::processEvents();
    componentTree->setCurrentItem(componentTree->topLevelItem(3));
    QApplication::processEvents();
    ok = check(labelFontSpin->value() == 0,
               "MemoText font=0 survives modify+switch+back (not reset to runtime default 16)") && ok;

    // 保存，验证 font=0 不被覆盖
    invoked = QMetaObject::invokeMethod(&window, "onSaveFile", Qt::DirectConnection);
    ok = check(invoked, "save MemoText font=0 preservation") && ok;

    const QString memoZeroText = readUtf8TextFile(memoZeroPath);
    ok = check(memoZeroText.contains("font=0"),
               "MemoText font=0 preserved after modify+switch+back+save") && ok;
    ok = check(!memoZeroText.contains("font=16") && !memoZeroText.contains("font=18"),
               "MemoText font=0 not overwritten to default after modify+switch+back+save") && ok;

    window.close();
    QApplication::processEvents();
    return ok;
}

// 测试 Scrollbar 默认值与运行时一致。
// 修复前：编辑器默认 style=0(horizontal), max=100；运行时默认 style=1(vertical), max=72。
// 修复后：编辑器默认 style=1, max=72，与运行时一致。
