    {
        MapFileEditor undoEditor;
        std::vector<uint8_t> undoBuffer = makeEmptyMapBuffer(2, 2);
        if (!check(undoEditor.loadFromBuffer(undoBuffer.data(), undoBuffer.size()),
                   "i18n: load map for undo command (en_US)"))
        {
            return false;
        }
        MapTileData tileData = undoEditor.getTile(0, 0);
        TileEditCommand tileCmd(0, 0, tileData, tileData, &undoEditor);
        ok = check(tileCmd.description() == QStringLiteral("Edit Tile (0, 0)"),
            "i18n: undo TileEdit description resolves to English at runtime in en_US") && ok;

        ComponentPropertyEditor propEditor;
        QLabel* widthLabel = propEditor.findChild<QLabel*>(QStringLiteral("menuWindowWidthLabel"));
        ok = check(widthLabel && widthLabel->text() == QStringLiteral("Width"),
            "i18n: ComponentPropertyEditor Width label renders English in en_US") && ok;
    }

    // High-2 回归：TrapScriptEditorDialog 已补 Q_OBJECT，其 tr() 现在解析到
    // "TrapScriptEditorDialog" context，译文在运行时真正生效。在 en_US 下构造实例，
    // 验证实际渲染的标题/表头为英文（缺 Q_OBJECT 时 tr() 会退回 QDialog context，
    // 即使目录里有译文，窗口仍显示简体中文源文）。
    {
        QTemporaryDir trapAssetsDir;
        QDir trapRoot(trapAssetsDir.path());
        trapRoot.mkpath(QStringLiteral("ini/save"));
        std::vector<uint8_t> trapBuffer = makeEmptyMapBuffer(2, 2);
        MapFileEditor trapMapEditor;
        if (!check(trapMapEditor.loadFromBuffer(trapBuffer.data(), trapBuffer.size()),
                   "i18n: load map for trap-script dialog"))
        {
            return false;
        }
        TrapScriptEditorDialog trapDialog(
            QStringLiteral("scene01"), trapAssetsDir.path(), &trapMapEditor);
        ok = check(trapDialog.windowTitle() ==
                       QStringLiteral("Trap Script Mapping Editor - scene01"),
            "i18n: trap-script dialog title renders English at runtime (Q_OBJECT context fix)") && ok;
        QTableWidget* trapTable = trapDialog.findChild<QTableWidget*>(
            QStringLiteral("trapScriptTable"));
        ok = check(trapTable && trapTable->horizontalHeaderItem(0) &&
                       trapTable->horizontalHeaderItem(0)->text() ==
                           QStringLiteral("Trap Index"),
            "i18n: trap-script dialog table header renders English at runtime") && ok;
    }

    // 切换到 zh_TW：已经打开的窗口同样即时刷新。
